require 'digest'
require 'securerandom'

class TokenStore
  def initialize
    @records = {}
  end

  def issue(user_id:, scope:)
    raw_token = SecureRandom.hex(32)
    @records[digest(raw_token)] = { user_id: user_id, scope: scope }
    raw_token
  end

  def authenticate(raw_token)
    @records[digest(raw_token)]
  end

  def revoke(raw_token)
    @records.delete(digest(raw_token))
  end

  private

  def digest(raw_token)
    Digest::SHA256.hexdigest(raw_token)
  end
end

store = TokenStore.new
token = store.issue(user_id: 42, scope: 'profile:read')
p store.authenticate(token)
store.revoke(token)
p store.authenticate(token)
